#!/bin/bash
set -e

# Deploy: WhatsApp invoice bill (PDF attached) -- auto-sends when an
# invoice becomes fully paid, plus a manual 'Send WhatsApp Bill' button
# on the Invoice Details screen.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/whatsapp.js"
echo "Wrote lib/whatsapp.js"

mkdir -p "app/(main)/billing"
echo "" | base64 -d > "app/(main)/billing/actions.js"
echo "Wrote app/(main)/billing/actions.js"

mkdir -p "app/(main)/payments"
echo "" | base64 -d > "app/(main)/payments/actions.js"
echo "Wrote app/(main)/payments/actions.js"

mkdir -p "app/(main)/billing/details"
echo "" | base64 -d > "app/(main)/billing/details/invoice-details-tab.js"
echo "Wrote app/(main)/billing/details/invoice-details-tab.js"

git add "lib/whatsapp.js" "app/(main)/billing/actions.js" "app/(main)/payments/actions.js" "app/(main)/billing/details/invoice-details-tab.js"
git commit -m "Add WhatsApp invoice bill (PDF attached): auto-send on full payment + manual button"
git push

echo "Done. Deployed WhatsApp invoice bill integration."
